// Upstream capture server for the provider-routing e2e.
// Two ports, each impersonating one "provider" upstream. Whichever port
// receives the chat/completions call is the provider the run actually routed
// to — an unambiguous end-to-end signal, independent of any log line.
const hits: Array<{ port: number; method: string; url: string; at: string }> = [];

function serve(port: number, label: string) {
  Bun.serve({
    port,
    hostname: "127.0.0.1",
    async fetch(req) {
      const url = new URL(req.url);
      hits.push({
        port,
        method: req.method,
        url: url.pathname,
        at: new Date().toISOString(),
      });
      console.log(`[HIT] ${label} port=${port} ${req.method} ${url.pathname}`);
      if (url.pathname.endsWith("/models")) {
        return Response.json({
          object: "list",
          data: [{ id: "e2e-model", object: "model" }],
        });
      }
      // Distinguishable terminal error so the run surfaces WHICH upstream ran.
      return new Response(
        JSON.stringify({ error: { message: `${label}-WAS-HIT`, type: "e2e" } }),
        { status: 402, headers: { "content-type": "application/json" } },
      );
    },
  });
  console.log(`capture ${label} listening on 127.0.0.1:${port}`);
}

serve(Number(process.argv[2] ?? 7801), "PROVIDER-ALPHA");
serve(Number(process.argv[3] ?? 7802), "PROVIDER-BRAVO");

process.on("SIGTERM", () => {
  console.log("HITS " + JSON.stringify(hits));
  process.exit(0);
});

