 * Map gateway provider slugs to model-registry provider names.
 * The gateway uses slugs like "z-ai" while the model registry uses "zai".
 */
export const PROVIDER_REGISTRY_ALIASES: Record<string, string> = {
  "z-ai": "zai",
};

